// Turing machine simulator for {0^n 1^n | n >= 0}
// Strategy: alternately mark leftmost 0 as X and rightmost 1 as Y.

function tmZeroN_OneN(input) {
  // Tape: extend with blanks on both sides
  const BLANK = '_';
  const tape = [BLANK, ...input.split(''), BLANK];
  let head = 1;       // start at first input symbol
  let state = 'q0';
  let steps = 0;
  const MAX_STEPS = 10000;

  while (steps++ < MAX_STEPS) {
    const sym = tape[head] ?? BLANK;

    if (state === 'q0') {
      if (sym === '0') {
        tape[head] = 'X';   // mark 0
        state = 'q1';       // now scan right for rightmost 1
        head++;
      } else if (sym === BLANK || sym === 'Y') {
        // No more unmarked 0s — check no unmarked 1s remain
        state = 'qScan';
        head++;
      } else {
        return 'REJECT';    // saw 1 before any 0
      }
    } else if (state === 'q1') {
      if (sym === '0' || sym === 'X') {
        head++; // skip over remaining 0s and markers
      } else if (sym === '1') {
        tape[head] = 'Y';   // mark rightmost 1 tentatively, keep scanning
        head++;
      } else if (sym === BLANK || sym === 'Y') {
        // Find last actual '1' (now marked Y) by scanning back
        head--;
        state = 'q2';
      } else {
        return 'REJECT';
      }
    } else if (state === 'q2') {
      // Scan left back to X (last marked 0)
      if (sym === '0' || sym === '1' || sym === 'Y') {
        head--;
      } else if (sym === 'X') {
        head++;  // position just right of X
        state = 'q0';
      } else if (sym === BLANK) {
        head++;
        state = 'q0';
      }
    } else if (state === 'qScan') {
      if (sym === 'Y' || sym === 'X') { head++; }
      else if (sym === BLANK) { return 'ACCEPT'; }
      else { return 'REJECT'; } // leftover unmarked 1
    }
  }
  return 'LOOP (exceeded step limit)';
}

// Tests
console.log(tmZeroN_OneN(''));       // ACCEPT  (n=0, epsilon)
console.log(tmZeroN_OneN('01'));     // ACCEPT  (n=1)
console.log(tmZeroN_OneN('0011'));   // ACCEPT  (n=2)
console.log(tmZeroN_OneN('001'));    // REJECT  (unequal)
console.log(tmZeroN_OneN('0111'));   // REJECT  (unequal)
console.log(tmZeroN_OneN('10'));     // REJECT  (wrong order)

// The halting problem: why no general solver can exist.
// We CANNOT write a real halts() — but we can illustrate the
// self-referential contradiction that makes it impossible.

// Hypothetical decider (NOT implementable for all cases)
// function halts(programSourceCode, input) {
//   // If this existed and always returned true/false correctly:
//   ...magic...
