//   if (halts(programSourceCode, programSourceCode)) {
//     while (true) {}   // loop if halts says HALT
//   } else {
//     return 'done';    // halt if halts says LOOP
//   }
// }

// Now ask: what does diagonal(diagonal) do?
// Case A: diagonal halts on its own code
//   => halts(diagonal, diagonal) returns true
//   => diagonal runs: while(true) {} => LOOPS
//   => Contradiction: we assumed it halts!
//
// Case B: diagonal loops on its own code
//   => halts(diagonal, diagonal) returns false
//   => diagonal runs: return 'done' => HALTS
//   => Contradiction: we assumed it loops!
//
// CONCLUSION: halts() cannot exist for all (program, input) pairs.

// ── What we CAN do: detect halting for specific cases ───────────

// We CAN detect a program that always terminates (trivially bounded loop)
function alwaysTerminates_example() {
  for (let i = 0; i < 100; i++) { /* nothing */ }
  return 'done';
}
// For THIS specific program, we know it halts — but that's static analysis
// of THIS program, not a general halts() decider.

// We CAN run a program and detect if it halted within N steps:
function runWithTimeout(fn, maxSteps) {
  // In JS we cannot truly interrupt synchronous execution,
  // but conceptually: run fn(), if it returns within maxSteps, HALT.
  // If it exceeds maxSteps: we don't know — it might halt at step N+1.
  try {
    const result = fn(); // if fn() returns, it halted
    return { halted: true, result };
  } catch (e) {
    return { halted: false, error: e.message };
  }
}

console.log(runWithTimeout(() => 42, 1000));          // { halted: true, result: 42 }
console.log(runWithTimeout(() => { throw 'err'; }, 1000)); // { halted: false }
// But a program that runs for 10^100 steps before returning
// would fool our timeout — we cannot distinguish 'loops forever'
// from 'runs for a very long time'.

// Rice's theorem in practice:
// Illustrating WHY linters and type checkers must be approximations.

// Property P: 'does this function ever return the number 42?'
// Rice's theorem: undecidable for arbitrary programs.

// WHAT STATIC ANALYSERS ACTUALLY DO: approximate with two strategies:

// Strategy 1: SOUND (no false negatives — never misses a real issue)
//   May produce false positives (flags safe code as problematic)
//   Example: conservative null-checker that flags EVERY dereference
function soundChecker(code) {
  // Overapproximates: if ANY execution path MIGHT return 42, flag it.
  // Result: never misses a real case, but cries wolf on safe code.
  // TypeScript's strict mode is approximately this for type safety.
  return 'MIGHT have issue'; // conservative
}

// Strategy 2: COMPLETE (no false positives — only flags real issues)
//   May miss real bugs (false negatives)
//   Example: only flag issues provably triggered by a specific test suite
function completeChecker(code) {
  // Underapproximates: only flags what is definitely provable.
  // Result: everything flagged is real, but real bugs may be missed.
  return 'DEFINITELY has issue'; // only when 100% certain
}

// REAL TOOLS and their trade-offs:
const tools = [
  { name: 'TypeScript',    approach: 'Sound for types, incomplete for logic' },
  { name: 'ESLint',        approach: 'Heuristic: catches common patterns, not all bugs' },
  { name: 'Valgrind',      approach: 'Dynamic (runtime), complete for executed paths' },
  { name: 'Formal Prover', approach: 'Sound+complete but requires specs & exponential time' },
];

tools.forEach(t => console.log(`${t.name}: ${t.approach}`));

// The fundamental constraint from Rice:
// No tool can be simultaneously sound, complete, and terminate for all programs.
// Every real-world linter/analyser makes one of these sacrifices.
console.log('\nRice\u2019s theorem: perfect static analysis is mathematically impossible.');
console.log('Every tool is an engineering trade-off, not a limitation of cleverness.');
